preConditionHook:
// THE AVERAGE DAILY RANGE -- the corpus's second session primitive. The mean
// high-low of the last dayLookback COMPLETED sessions. Deliberately not an
// ATR of daily bars: there is no gap term, because "the range of recent days"
// is what Brooks means and what his 25-30-50 percent readings are quoted
// against. As a filter the rule says only that the average is available;
// OpeningRangeVsAvgDailyRange and AvgDailyRangeFractionStop inline this same
// block for the value.
//
// WHY A BAR SCAN AND NOT HighD/LowD: HighD(n)/LowD(n) are VERIFIED but have
// no engine counterpart, so this twin would have to reconstruct them anyway,
// and the stateful mirror FailedBreakoutOfPriorSessionExtreme uses only
// reaches ONE prior day. Scanning the bar series in BOTH twins keeps them
// structurally identical and makes the reach a single stated input. The
// slicing is the same: the xxxD family's day IS the wall-clock calendar date,
// the same boundary as date <> date[1] (EL_FEATURES highd/lowd row).
//
// THE SCAN: walk back from bar 1. Bars carrying the CURRENT date are skipped,
// so today's incomplete session never enters the average -- what is averaged
// is exactly HighD(1..dayLookback) - LowD(1..dayLookback). A day group opens
// on the first bar of a new date encountered and closes when bar kk is the
// oldest bar of its date, day_of(Time(kk + 1)) != day_of(Time(kk)); that read
// is what makes the deepest index maxScanBars + 1.
//
// The dayLookback guard WRAPS the date read rather than being ANDed with it:
// EasyLanguage does not short-circuit and/or, so nesting is the only spelling
// in which a finished scan touches no further history in both twins.
//
// maxScanBars MUST COVER dayLookback SESSIONS OF BARS and Max Bars Back must
// cover maxScanBars + 1. On a daily or 1440-minute series one bar is one
// session, so dayLookback + 1 is enough. On finer intraday bars set it to at
// least dayLookback x bars per session; if the scan runs out first, adrDays
// stays short, adrReady is false, and the rule is silent rather than wrong.
//
// Direction-agnostic, so both sides are identical text.
adrSum = 0.0;
adrDays = 0;
dHi = 0.0;
dLo = 0.0;
dOpen = false;
for (int kk = 1; kk <= (int)maxScanBars; ++kk) {
    if (el_lt((double)adrDays, dayLookback)) {
        if (day_of(ctx.Time(kk)) != day_of(ctx.Time(0))) {
            if (!dOpen) {
                dHi = high[kk];
                dLo = low[kk];
                dOpen = true;
            } else {
                if (el_gt(high[kk], dHi)) dHi = high[kk];
                if (el_lt(low[kk], dLo)) dLo = low[kk];
            }
            if (day_of(ctx.Time(kk + 1)) != day_of(ctx.Time(kk))) {
                adrSum = adrSum + (dHi - dLo);
                adrDays = adrDays + 1;
                dOpen = false;
            }
        }
    }
}
adrReady = el_ge((double)adrDays, dayLookback);
if (adrReady) {
    adr = adrSum / dayLookback;
} else {
    adr = 0.0;
}
